  async function readKpiJson(response) { const raw=await response.text(); if(!raw.trim())throw new Error(`The performance server returned an empty response (${response.status}).`); if(!(response.headers.get('content-type')||'').toLowerCase().includes('application/json')){console.error('Performance response was not JSON:',raw.slice(0,500));throw new Error('The performance server returned an invalid response.');} let data;try{data=JSON.parse(raw);}catch(error){console.error('Performance response could not be parsed:',raw.slice(0,500),error);throw new Error('The performance server returned incomplete data.');}if(!response.ok||data.ok!==true)throw new Error(data.message||`Performance request failed (${response.status}).`);return data; }
