  function activateEmployeeSection(key,updateUrl=false){if(key==='order-packing')key='orders';const selected=employeeSections.includes(key)?key:'orders',visiblePanels=sectionPanels[selected];root.dataset.activeSection=selected;root.querySelectorAll('.employee-kpi-section').forEach(panel=>{panel.hidden=!visiblePanels.includes(panel.id);});root.querySelectorAll('[data-employee-section]').forEach(link=>{const active=link.dataset.employeeSection===selected;link.classList.toggle('active',active);link.setAttribute('aria-current',active?'page':'false');});if(updateUrl){const url=new URL(location.href);url.searchParams.set('section',selected);history.replaceState(null,'',url);} }
