  const cards = (metrics = [], evidenceKey = '') => {const excluded=metrics.find(m=>m.label==='Unclear Historical Responsibility'),visible=metrics.filter(m=>m.label!=='Unclear Historical Responsibility');return `<div class="employee-kpi-metrics">${visible.map((m) => { const help=metricHelp[m.label]||m.explanation||''; const missing=m.value===null||m.value===undefined; const coverage=m.denominator !== undefined&&m.denominator !== null?(m.numerator!==undefined&&m.numerator!==null?`${esc(m.numerator)} of ${esc(m.denominator)} eligible records`:`n = ${esc(m.denominator)}`):esc(missing ? (m.status==='not_applicable'?'Not applicable to this role':'Insufficient historical data') : (m.explanation||''));return `<article class="kpi-health-card ${missing?'is-unmeasured':''}"><span>${esc(m.label)}${help?` <button type="button" class="kpi-info-button" title="${esc(help)}" aria-label="About ${esc(m.label)}" data-kpi-help="${esc(help)}">i</button>`:''}</span><strong class="kpi-number">${esc(value(m))}</strong><small>${coverage}</small>${m.source?`<small>Source: ${esc(m.source)}</small>`:''}${evidenceKey?`<button type="button" class="kpi-view-evidence" data-kpi-evidence-section="${esc(evidenceKey)}">View Evidence</button>`:''}</article>`; }).join('')}</div>${excluded?`<aside class="kpi-historical-exclusion"><div><strong>Historical data excluded</strong><span>${esc(value(excluded))} older orders are missing reliable timing evidence and are not counted in this employee's score.</span></div>${evidenceKey?`<button type="button" class="kpi-view-evidence" data-kpi-evidence-section="${esc(evidenceKey)}">Review records</button>`:''}</aside>`:''}`;};
