  function frontDeskOrdersHtml(data={}){const duties=data.duty_analysis||{},mix=data.mode_mix||[],performance=data.mode_performance||[],risk=data.risk_flags||{},score=data.orders_score,pending=(data.pending_orders?.length?data.pending_orders:(data.rows||[]).filter(row=>row.pending_timing));const pendingTimeline=`<section class="kpi-pending-timeline"><header><div><h3>Pending Completion Timeline</h3><p>Current In Progress orders and the time remaining under each applicable rule.</p></div><span>${pending.length} pending</span></header><div>${pending.map(row=>{const timing=row.pending_timing||{},remaining=timing.remaining_minutes===null||timing.remaining_minutes===undefined?'Paused':durationMinutes(timing.remaining_minutes),elapsed=timing.elapsed_minutes===null||timing.elapsed_minutes===undefined?'Not counting':durationMinutes(timing.elapsed_minutes);return `<article class="is-${esc(timing.state||'review')}"><div><strong>${esc(row.order_number||'Order')}</strong><span>${esc(row.customer_name||'Customer')} · ${esc(row.mode||'Mode not recorded')}</span></div><b>${esc(timing.label||'Timing review')}</b><dl><div><dt>Counted time</dt><dd>${elapsed}</dd></div><div><dt>${timing.state==='review_due'?'Review status':'Time remaining'}</dt><dd>${timing.state==='review_due'?'Due now':remaining}</dd></div></dl><small>${timing.scored?'Counts toward completion timing':'External or paused time — not scored against the employee'}</small><button type="button" class="btn-secondary kpi-record-link" data-timeline-module="order" data-timeline-id="${Number(row.id)}">View activity</button></article>`;}).join('')||'<div class="kpi-empty-state">No In Progress orders remain for this period.</div>'}</div></section>`;return `${cards(data.metrics,'orders')}${pendingTimeline}<div class="kpi-front-duty-grid">${dutyCard('Walk-ins · New → Complete',duties.walk_in)}${dutyCard('Other Front Desk · Ready/In Progress → Complete',duties.other_front_desk)}${dutyCard('Overall front-desk completion',duties.overall)}</div><section class="kpi-front-score"><div class="kpi-front-score__ring" style="--front-score:${Number(score||0)}"><strong>${score===null||score===undefined?'—':`${Number(score).toFixed(1)}%`}</strong><span>${score===null||score===undefined?'Not enough data':'Orders score'}</span></div><div><h3>How the Order Score Is Calculated</h3><p>${esc(data.score_detail?.methodology||'Central Orders component only.')}</p><p>Walk-ins: ${data.score_detail?.walk_in_rate??'—'}% at ${data.score_detail?.walk_in_weight??0}% configured duty weight · Other Front Desk: ${data.score_detail?.non_walk_weight??0}%.</p><p>Coverage: ${Number(duties.overall?.compliance_denominator||0)} completed eligible orders. Status: Provisional.</p></div></section><div class="kpi-front-analysis"><section><h3>Order Mix</h3>${distribution(mix.map(row=>({result:row.mode,count:row.count})).flatMap(row=>Array.from({length:row.count},()=>({result:row.result}))),'result')}</section><section><h3>On-Time Results by Order Type</h3>${performance.map(row=>`<div class="kpi-mode-stack"><span>${esc(row.mode)}</span><i style="--on:${Number(row.on_time||0)};--late:${Number(row.late||0)};--pending:${Number(row.pending||0)}"></i><b>${Number(row.on_time||0)} on time · ${Number(row.late||0)} late · ${Number(row.pending||0)} pending</b></div>`).join('')||'<p>No applicable modes.</p>'}</section></div><section class="kpi-front-risk"><h3>Risk flags</h3>${Object.entries(risk).map(([label,count])=>`<span class="${Number(count)>0?'has-risk':''}">${esc(label.replaceAll('_',' '))}<b>${Number(count||0)}</b></span>`).join('')}</section>`;}
