    const schedule=data.schedule||{},scheduleNote=schedule.configured?`Schedule effective ${schedule.effective_from||'from the configured date'}${schedule.effective_to?` to ${schedule.effective_to}`:''}; ${schedule.timezone||'Africa/Windhoek'}; lunch ${schedule.lunch_start?.slice(0,5)||'not set'}–${schedule.lunch_end?.slice(0,5)||'not set'}; ${schedule.late_grace_minutes} minute grace. Portal Presence supports a limited Portal Schedule Compliance contribution; it is not formal attendance.`:'No reliable employee schedule is configured; Portal Schedule Compliance is Not Measured.';
