  async function showPresenceTimeline(evidenceDate){const dialog=q('[data-kpi-timeline]'),target=q('[data-kpi-timeline-content]');target.innerHTML='<p>Loading daily portal evidence…</p>';dialog.showModal();try{const response=await fetch(`kpi-employee-data.php?id=${id}&action=presence_timeline&date=${encodeURIComponent(evidenceDate)}`,{headers:{Accept:'application/json'}}),data=await readKpiJson(response);const filters=['all','authentication','orders','packing_list','tasks','courier_waybills','bookkeeping','error_log','inactive_period'];target.innerHTML=`<h2>Portal Activity · ${esc(data.date)}</h2><p>Authenticated and workflow evidence for ${esc(data.employee.name)}. Times are shown in Africa/Windhoek. No portal activity is not proof of physical absence.</p><div class="kpi-timeline-filters">${filters.map((filter)=>`<button type="button" data-presence-filter="${esc(filter)}">${esc(filter.replaceAll('_',' '))}</button>`).join('')}</div><div class="kpi-daily-timeline">${data.events.length?data.events.map((item)=>`<article data-presence-event="${esc(item.event_type)}" data-presence-module="${esc(item.module)}"><time>${esc(String(item.occurred_at).slice(11,16))}${item.ended_at?`–${esc(String(item.ended_at).slice(11,16))}`:''}</time><div><strong>${esc(item.action)}</strong><span>${esc(item.module)}${item.record_reference?` · ${esc(item.record_reference)}`:''}</span><small>Source: ${esc(item.source_log)}${item.source_event_id?` #${esc(item.source_event_id)}`:''}${item.contributes_kpi?' · Performance evidence':''}</small></div></article>`).join(''):'<p>Historical evidence unavailable. This date is excluded from scoring.</p>'}</div>`;}catch(error){target.innerHTML=`<p class="ops-alert error">${esc(error.message)}</p>`;}}
  root.addEventListener('click',async(event)=>{const sectionTab=event.target.closest('[data-employee-section]');if(sectionTab){event.preventDefault();activateEmployeeSection(sectionTab.dataset.employeeSection,true);return;}const help=event.target.closest('[data-kpi-help]');if(help)alert(help.dataset.kpiHelp);const evidence=event.target.closest('[data-kpi-evidence-target]');if(evidence){const target=q(evidence.dataset.kpiEvidenceTarget);target?.scrollIntoView({behavior:'smooth',block:'start'});target?.focus({preventScroll:true});}const allocation=event.target.closest('[data-confirm-bookkeeping-allocation]');if(allocation){const entryId=prompt('Bookkeeping entry ID to allocate to this order:')?.trim(),amount=prompt('Cash amount allocated:',Number(allocation.dataset.cashExpected||0).toFixed(2))?.trim(),note=prompt('Supporting evidence or reason (required):')?.trim();if(!entryId||!amount||!note)return;allocation.disabled=true;const body=new FormData();body.set('csrf_token',root.dataset.presenceCsrf||'');body.set('order_id',allocation.dataset.orderId);body.set('bookkeeping_entry_id',entryId);body.set('cash_amount',amount);body.set('note',note);try{const response=await fetch('kpi-bookkeeping-allocation.php',{method:'POST',body,headers:{Accept:'application/json'}});await readKpiJson(response);await load(true);}catch(error){alert(error.message);allocation.disabled=false;}return;}const timelineLink=event.target.closest('[data-timeline-module]');if(timelineLink)showTimeline(timelineLink.dataset.timelineModule,timelineLink.dataset.timelineId);if(event.target.closest('[data-kpi-timeline-close]'))q('[data-kpi-timeline]').close();});
  const toggle=()=>root.querySelectorAll('[data-kpi-custom]').forEach((node)=>node.hidden=period.value!=='custom'); const changed=()=>{toggle();const url=new URL(location.href);url.searchParams.set('period',period.value);if(period.value==='custom'){url.searchParams.set('date_from',from.value);url.searchParams.set('date_to',to.value);}else{url.searchParams.delete('date_from');url.searchParams.delete('date_to');}history.replaceState(null,'',url);if(period.value!=='custom'||(from.value&&to.value))load();}; period.addEventListener('change',changed);from.addEventListener('change',changed);to.addEventListener('change',changed);
  const query=new URLSearchParams(location.search),selected=query.get('period')||'last_month';if([...period.options].some((option)=>option.value===selected))period.value=selected;from.value=query.get('date_from')||'';to.value=query.get('date_to')||'';toggle();load();document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')refreshLivePresence();else{window.clearTimeout(livePresenceTimer);livePresenceController?.abort();}});window.addEventListener('beforeunload',()=>{window.clearTimeout(livePresenceTimer);livePresenceController?.abort();});
  function frontOrderEvidence(data={}){const rows=data.rows||[];return `<section class="kpi-order-evidence-list"><header><div><p class="eyebrow">Source records behind the widgets</p><h2>Orders Used in This Calculation</h2><p>This is not every portal order. It contains the ${rows.length} orders attributed to this employee for the selected period. Payment and completion history are shown together so each result can be checked.</p></div><span>${rows.length} orders</span></header><div class="kpi-order-evidence-items">${rows.map(row=>`<article class="kpi-order-evidence-item"><div class="kpi-order-evidence-item__title"><div><strong>${esc(row.order_number||'Order')}</strong><span>${esc(row.customer_name||'Customer not recorded')}</span></div><b>${esc(row.result||'Awaiting review')}</b></div><dl><div><dt>Why included</dt><dd>${esc(row.attribution_source||'—')}</dd></div><div><dt>Duty and mode</dt><dd>${esc(row.front_desk_category||'—')} · ${esc(row.mode||'—')}</dd></div><div><dt>Assigned employee</dt><dd>${esc(row.packed_by||'Unassigned')}</dd></div><div><dt>Current status</dt><dd>${esc(row.status||'—')}</dd></div><div><dt>Paid</dt><dd>${esc(row.paid_status||'Not paid')}<small>${row.payment_recorded_at?`${date(row.payment_recorded_at)} · ${esc(row.payment_recorded_by||'Employee not recorded')}`:'No payment timestamp recorded'}</small></dd></div><div><dt>Complete</dt><dd>${row.completed_at?date(row.completed_at):'Not completed'}<small>${esc(row.completed_by||'Employee not recorded')}</small></dd></div><div><dt>Performance clock</dt><dd>${esc(row.clock_basis||'—')}<small>${row.clock_start?`Started ${date(row.clock_start)}`:'Clock paused / not started'}</small></dd></div><div><dt>Counted duration</dt><dd>${row.duration_minutes===null||row.duration_minutes===undefined?'Paused / not scored':durationMinutes(row.duration_minutes)}</dd></div></dl><footer><span>${esc(row.evidence_id||'Current order record')}</span>${row.timeline_module&&row.id?`<button type="button" class="btn-secondary kpi-record-link" data-timeline-module="${esc(row.timeline_module)}" data-timeline-id="${Number(row.id)}">View complete activity</button>`:''}</footer></article>`).join('')||'<div class="kpi-empty-state">No orders were used in this calculation for the selected period.</div>'}</div></section>`;}
  function showSectionEvidence(key){const data=root._kpiData,sectionData=data?.sections?.[key],dialog=q('[data-kpi-timeline]'),target=q('[data-kpi-timeline-content]');if(!sectionData||!dialog||!target)return;const columns=key==='orders'&&sectionData.packer_orders?cols.packerOrders:key==='packing'&&sectionData.packing_list_performance?cols.packingPerformance:key==='packing'&&sectionData.front_packing_list_kpi?cols.frontPacking:key==='tasks'&&sectionData.task_management_performance?cols.taskPerformance:cols[key];target.innerHTML=key==='orders'&&!sectionData.packer_orders?frontOrderEvidence(sectionData):`<header class="kpi-evidence-heading"><p class="eyebrow">Authoritative evidence</p><h2>${esc(definitions[key]?.[0]||key)}</h2><p>Full timestamps and source records are shown here only. ${Number((sectionData.rows||[]).length)} matching records.</p></header>${key==='bookkeeping'?bookkeepingEvidence(sectionData):table(columns,sectionData.rows||[])}`;dialog.classList.toggle('is-order-evidence',key==='orders'&&!sectionData.packer_orders);dialog.showModal();}
  function setPresentation(open){const panels=[...root.querySelectorAll('[data-kpi-slide-panel]')],controls=q('[data-kpi-presentation-controls]');root.classList.toggle('is-presentation',open);controls.hidden=!open;root._kpiSlide=0;const show=()=>{panels.forEach((panel,index)=>panel.hidden=open&&index!==root._kpiSlide);const status=q('[data-kpi-slide-status]');if(status)status.textContent=open?`${root._kpiSlide+1} / ${panels.length}`:'';};show();if(open)root.requestFullscreen?.().catch(()=>{});else if(document.fullscreenElement)document.exitFullscreen?.();root._showKpiSlide=show;}
  root.addEventListener('click',(event)=>{const sectionEvidence=event.target.closest('[data-kpi-evidence-section]');if(sectionEvidence){event.stopImmediatePropagation();showSectionEvidence(sectionEvidence.dataset.kpiEvidenceSection);return;}if(event.target.closest('[data-kpi-presentation]')){event.stopImmediatePropagation();setPresentation(true);return;}if(event.target.closest('[data-kpi-presentation-exit]')){event.stopImmediatePropagation();setPresentation(false);return;}const slide=event.target.closest('[data-kpi-slide]');if(slide){event.stopImmediatePropagation();const panels=[...root.querySelectorAll('[data-kpi-slide-panel]')],delta=slide.dataset.kpiSlide==='next'?1:-1;root._kpiSlide=Math.max(0,Math.min(panels.length-1,(root._kpiSlide||0)+delta));root._showKpiSlide?.();}},true);
  document.addEventListener('keydown',(event)=>{if(!root.classList.contains('is-presentation'))return;if(event.key==='Escape')setPresentation(false);if(event.key==='ArrowRight'||event.key==='ArrowLeft'){const panels=[...root.querySelectorAll('[data-kpi-slide-panel]')],delta=event.key==='ArrowRight'?1:-1;root._kpiSlide=Math.max(0,Math.min(panels.length-1,(root._kpiSlide||0)+delta));root._showKpiSlide?.();}});
